const keys=new Set(),pressed=new Set();
function clearInput(){keys.clear();pressed.clear();}
addEventListener('keydown',e=>{if(e.target?.tagName==='BUTTON'&&['Space','Enter'].includes(e.code))return;if(['Space','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.code)&&phase==='play'&&!paused&&e.target?.tagName!=='BUTTON')e.preventDefault();if(e.code==='Escape'&&!e.repeat){if(phase==='play'||phase==='opening'||phase==='setback')togglePause();else if(!$('pause-panel').hidden)$('pause-panel').hidden=true;return;}if(phase!=='play'||paused)return;if(!e.repeat&&!keys.has(e.code))pressed.add(e.code);keys.add(e.code)});
addEventListener('keyup',e=>keys.delete(e.code));
