addEventListener('blur',autoPause);document.addEventListener('visibilitychange',()=>{if(document.hidden)autoPause();});
document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();if(phase!=='play'||paused||keys.has(b.dataset.key))return;b.setPointerCapture?.(e.pointerId);keys.add(b.dataset.key);pressed.add(b.dataset.key)};b.onpointerup=b.onpointercancel=b.onlostpointercapture=()=>keys.delete(b.dataset.key)});
function totalItems(){return things.filter(o=>o.kind==='item').length+bag.length+scales.reduce((n,s)=>n+s.items.length,0);}
function spawn(def,x,y,vx=0,kind='item'){if(kind==='item'&&totalItems()>=TOTAL_ITEM_LIMIT)return null;if(kind!=='item'&&things.filter(o=>o.kind!=='item').length>=HAZARD_LIMIT)return null;if(kind==='shard'&&things.filter(o=>o.kind==='shard').length>=SHARD_LIMIT)return null;const stage=Math.max(checkpoint,Math.min(4,Math.floor((player?.y??0)/5))),size=difficultyFor(stage).heartScale;if(kind==='item')def=createItem(def,stage);const g=kind==='item'?itemMesh(def):new T.Group();if(kind==='heart'||kind==='shard'){g.add(itemAssets.sprite('HEART'));}if(kind==='shard')g.scale.setScalar(.32*size);else if(kind==='heart')g.scale.setScalar(size);if(kind==='tear'){ball(0,0,0,.3,0x81cee3,g);const tip=new T.Mesh(new T.ConeGeometry(.23,.5,5),material(0x81cee3));tip.position.y=.3;g.add(tip)}if(kind==='item'){const artScale=looseArtScale(def);g.children[0].scale.multiplyScalar(artScale);g.children[0].position.y*=artScale;}g.position.set(x,y,.6);scene.add(g);if(kind==='roses'||kind==='giftbomb'){const icon=itemAssets.sprite(kind==='roses'?'FLOWERS':'GIFT');icon.material=icon.material.clone();g.add(icon);g.userData.icon=icon;}const timer=kind==='item'||kind==='giftbomb'?countdownSprite(g):null;things.push({id:++labelId,def,x,y,vx,vy:0,g,kind,size,timer,bounces:0,age:0,rest:false});return things.at(-1)}
function floorItems(y){return things.filter(o=>o.kind==='item'&&(o.deliveryY===y||Math.abs(o.y-y)<3));}
function nextSupply(y){if(things.filter(o=>o.kind==='item').length>=LOOSE_ITEM_LIMIT||totalItems()>=TOTAL_ITEM_LIMIT)return null;if(floorItems(y).length>=laneLimit(y/5))return null;const loose=floorItems(y).map(o=>o.def),local=scales.filter(s=>s.y===y&&!s.solved).sort((a,b)=>Number(a.optional)-Number(b.optional));const needed=local.map(requiredWeight),available=[...loose,...bag],missing=needed.find(w=>available.filter(d=>d.w===w).length<(w===2?2:1)),weight=missing??needed[0]??1;return chooseSupply(ITEMS,loose,bag,weight,supplyIndex++);}
function tossBelonging(def,y){const spot=chooseStaging({y,scales,things,def,preferredX:[-10,0,10][supplyIndex%3]});if(!spot)return null;const flight=(3+Math.sqrt(9+32*(25-y)))/16;const o=spawn({...def,armed:false},4.65,25,(spot.x-4.65)/flight);if(o){o.vy=3;o.deliveryY=y;o.flyingDelivery=true;o.z=spot.z;}return o;}
