 kickSprite.visible=t<.7;woman.visible=t>=.7&&t<SLAM_AT;woman.setPose(1);woman.position.set(5.8,BALCONY_Y,.1-Math.max(0,t-.7)*2.4);doorHinge.rotation.y=t<.7?0:t<1.35?-(t-.7)*1.75:t<SLAM_AT?-1.14*(SLAM_AT-t)/.2:0;
 $('opening-caption').hidden=false;$('opening-caption').textContent=t<BOX_HIT_AT?'ONE LAST TRY.':t<SLAM_AT?'RETURN TO SENDER.':t<2.6?'THAT DOOR CLOSED.':'GET THE CARD. KEEP GOING.';
 if(t>=SLAM_AT&&!slammed){slammed=true;slamDust.visible=true;sound(48,.7,'sine');sound(135,.22,'triangle');slamSound();emit('door:slam');}
