if(player.y<-3){player.y=checkpoint*5+1;player.x=0;player.vy=0;hurt()}if(pressed.has('ArrowDown')||pressed.has('KeyS')||pressed.has('Space')||pressed.has('KeyE'))act();if(phase!=='play'&&phase!=='opening'){hud();return;}if(pressed.has('KeyQ'))placeItem();if(pressed.has('KeyR'))unload();if(pressed.has('KeyF'))adjustLever();
