for(const g of gifts){g.g.position.set(g.x,g.y+.8+Math.sin(time*2)*.1,.5);if(scales[4].solved&&!collected.has('CARD')&&phase==='play'&&Math.abs(player.x-g.x)<.8&&Math.abs(player.y-g.y)<1.1){collected.add('CARD');g.g.visible=false;cardCarry.visible=true;quest=quest==='recover'?'climb':'cross';score+=300;sound(1100,.3);toast(questHint(quest));emit('card:collect',{quest});}}
