if(quest!=='recover'&&quest!=='climb'){boxMesh.position.set(woman.position.x-1.15,woman.position.y+.75,.3);boxMesh.visible=true;}
if(refill>0){refill-=dt;woman.position.x=5.8;if(refill<=0){boxNo=Math.min(3,boxNo+1);throws=0;boxMesh.visible=true;sound(65,.4,'triangle');}}
